const input = $input.first().json.body;
const sqft = input.squareFootage || 1500;
const yearBuilt = input.yearBuilt || 1980;
const condition = input.condition || 'fair'; // good, fair, poor
const metro = input.metro || 'national_average';

// Base cost per sqft by condition
const baseCosts = {
  good: { low: 10, mid: 20, high: 30 },
  fair: { low: 25, mid: 45, high: 65 },
  poor: { low: 60, mid: 90, high: 150 }
};

const costs = baseCosts[condition] || baseCosts.fair;

// Age-based adjustments
let ageMultiplier = 1.0;
if (yearBuilt < 1950) ageMultiplier = 1.4;
else if (yearBuilt < 1970) ageMultiplier = 1.25;
else if (yearBuilt < 1990) ageMultiplier = 1.1;

// Critical items by age
const criticalItems = [];
const currentYear = new Date().getFullYear();
const age = currentYear - yearBuilt;

if (yearBuilt < 1950) {
  criticalItems.push({ item: 'Foundation inspection', priority: 'critical', estCost: '$5,000-$25,000' });
  criticalItems.push({ item: 'Knob & tube wiring check', priority: 'critical', estCost: '$8,000-$15,000' });
  criticalItems.push({ item: 'Lead paint remediation', priority: 'critical', estCost: '$1,000-$5,000/room' });
}
if (yearBuilt < 1980) {
  criticalItems.push({ item: 'Asbestos testing', priority: 'major', estCost: '$1,500-$3,000/area' });
  criticalItems.push({ item: 'Electrical panel upgrade', priority: 'major', estCost: '$2,500-$5,000' });
}
if (yearBuilt >= 1978 && yearBuilt <= 1995) {
  criticalItems.push({ item: 'Polybutylene pipe check', priority: 'major', estCost: '$5,000-$10,000' });
}
if (age > 20) {
  criticalItems.push({ item: 'Roof replacement likely', priority: 'major', estCost: '$8,000-$15,000' });
}
if (age > 15) {
  criticalItems.push({ item: 'HVAC replacement likely', priority: 'moderate', estCost: '$5,000-$10,000' });
  criticalItems.push({ item: 'Water heater replacement', priority: 'moderate', estCost: '$1,000-$2,000' });
}

const estimate = {
  squareFootage: sqft,
  yearBuilt: yearBuilt,
  condition: condition,
  ageMultiplier: ageMultiplier,
  budgetRange: {
    low: Math.round(costs.low * sqft * ageMultiplier),
    mid: Math.round(costs.mid * sqft * ageMultiplier),
    high: Math.round(costs.high * sqft * ageMultiplier)
  },
  criticalItems: criticalItems,
  recommendation: `Based on ${sqft} sqft, built ${yearBuilt} (${age} years old), in ${condition} condition: budget $${Math.round(costs.mid * sqft * ageMultiplier).toLocaleString()} for a ${condition === 'poor' ? 'gut' : condition === 'fair' ? 'medium' : 'light'} rehab. Add 10-15% contingency.`
};

return [{ json: estimate }];
